private void checkOcServer() {
  String uri;
  if (accountSetupBinding != null && accountSetupBinding.hostUrlInput.getText() != null && !accountSetupBinding.hostUrlInput.getText().toString().isEmpty()) {
    uri = accountSetupBinding.hostUrlInput.getText().toString().trim();
  } else {
    uri = mServerInfo.mBaseUrl;
  }
  mServerInfo = new GetServerInfoOperation.ServerInfo();
  if (uri.length() != 0) {
    try {
      if (accountSetupBinding != null) {
        uri = AuthenticatorUrlUtils.stripIndexPhpOrAppsFiles(uri);
        accountSetupBinding.hostUrlInput.setText(uri);
      }
      uri = AuthenticatorUrlUtils.normalizeScheme(uri);
      uri = DisplayUtils.convertIdn(uri, true);

      if (accountSetupBinding != null) {
        mServerStatusText = getResources().getString(R.string.auth_testing_connection);
        mServerStatusIcon = R.drawable.progress_small;
        showServerStatus();
      }

      Intent getServerInfoIntent = new Intent();
      getServerInfoIntent.setAction(OperationsService.ACTION_GET_SERVER_INFO);
      getServerInfoIntent.putExtra(OperationsService.EXTRA_SERVER_URL, AuthenticatorUrlUtils.normalizeUrlSuffix(uri));

      if (mOperationsServiceBinder != null) {
        mWaitingForOpId = mOperationsServiceBinder.queueNewOperation(getServerInfoIntent);
      } else {
        Log_OC.e(TAG, "Server check tried with OperationService unbound!");
      }
    } catch (PatternSyntaxException | IllegalArgumentException | NullPointerException | IndexOutOfBoundsException e) {
      Log_OC.e(TAG, "Error processing server URI: " + uri, e);
      if (accountSetupBinding != null) {
        mServerStatusText = getResources().getString(R.string.auth_connection_established);
        mServerStatusIcon = R.drawable.ic_status_fail;
        showServerStatus();
      }
    }
  }
}
